import React, { useState, useEffect } from 'react';
import LanguageSelector from './components/LanguageSelector';
import ChatBox from './components/ChatBox';
import LearningDashboard from './components/LearningDashboard';
import { fetchSupportedLanguages, createConversation, sendMessage, fetchMessages } from './services/api';
import { Globe, MessageSquare, BookOpen, Repeat, Cpu } from 'lucide-react';
import './styles/globals.css';

function App() {
  const [languages, setLanguages] = useState({});
  const [selectedLang, setSelectedLang] = useState('es');
  const [username, setUsername] = useState('user1');
  const [conversationId, setConversationId] = useState(null);
  const [messages, setMessages] = useState([]);
  const [mode, setMode] = useState('general');

  useEffect(() => {
    initApp();
  }, []);

  const initApp = async () => {
    try {
      const langData = await fetchSupportedLanguages();
      setLanguages(langData.languages || {});
      startNewConversation('es', 'general');
    } catch (e) {
      console.error("App init error:", e);
    }
  };

  const startNewConversation = async (langCode, selectedMode) => {
    try {
      const res = await createConversation(username, `${username}@matholy.ai`, langCode, selectedMode);
      setConversationId(res.conversation_id);
      setSelectedLang(langCode);
      setMode(selectedMode);
      setMessages([]);
    } catch (e) {
      console.error("Error creating conversation:", e);
    }
  };

  const handleSendMessage = async (text) => {
    if (!conversationId) return;

    // Optimistic user message insertion
    const tempUserMsg = { sender: 'user', content: text, detected_language: selectedLang };
    setMessages((prev) => [...prev, tempUserMsg]);

    try {
      const res = await sendMessage(conversationId, text);
      setMessages((prev) => [
        ...prev.slice(0, -1),
        res.user_message,
        res.assistant_message
      ]);
    } catch (e) {
      console.error("Error sending message:", e);
    }
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100vh', padding: '16px 24px', gap: '16px' }}>
      {/* Top Navbar */}
      <header className="glass-panel" style={{ padding: '12px 24px', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
          <div style={{ background: 'linear-gradient(135deg, #3b82f6, #ec4899)', width: '38px', height: '38px', borderRadius: '10px', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            <Globe color="#fff" size={22} />
          </div>
          <div>
            <h1 style={{ fontSize: '18px', fontWeight: 700, background: 'linear-gradient(90deg, #fff, #93c5fd)', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent' }}>
              Matholy Multilingual AI
            </h1>
            <p style={{ fontSize: '11px', color: '#94a3b8' }}>51 Global Languages • Neural Translation • Voice STT/TTS</p>
          </div>
        </div>

        {/* Mode Switcher */}
        <div style={{ display: 'flex', background: 'rgba(255, 255, 255, 0.05)', padding: '4px', borderRadius: '12px', gap: '4px' }}>
          {[
            { id: 'general', label: 'Chat', icon: MessageSquare },
            { id: 'tutor', label: 'Tutor', icon: BookOpen },
            { id: 'translator', label: 'Translate', icon: Repeat },
          ].map((m) => {
            const Icon = m.icon;
            return (
              <button
                key={m.id}
                onClick={() => startNewConversation(selectedLang, m.id)}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '6px',
                  padding: '8px 14px',
                  borderRadius: '8px',
                  border: 'none',
                  fontSize: '13px',
                  fontWeight: 500,
                  cursor: 'pointer',
                  background: mode === m.id ? 'linear-gradient(135deg, #3b82f6, #8b5cf6)' : 'transparent',
                  color: mode === m.id ? '#fff' : '#94a3b8'
                }}
              >
                <Icon size={14} />
                {m.label}
              </button>
            );
          })}
        </div>

        {/* Language Selector */}
        <LanguageSelector 
          languages={languages} 
          selectedLang={selectedLang} 
          onSelectLanguage={(lang) => startNewConversation(lang, mode)} 
        />
      </header>

      {/* Main Container */}
      <main style={{ flex: 1, display: 'flex', gap: '20px', overflow: 'hidden' }}>
        <ChatBox 
          messages={messages} 
          onSendMessage={handleSendMessage} 
          selectedLang={selectedLang}
          username={username}
          languages={languages}
        />
        <LearningDashboard 
          username={username} 
          selectedLang={selectedLang} 
          languages={languages} 
        />
      </main>
    </div>
  );
}

export default App;
